WITH filtered AS (SELECT *, FLOOR(rating) AS rating_whole, COALESCE(city, 'UNKNOWN') AS resolved_city FROM suppliers WHERE city IS NOT NULL), valid AS (SELECT id, supplier_name, rating, rating_whole, resolved_city, INITCAP(TRIM(country)) AS country_title, COALESCE(city, 'DIRECT') AS city_filled FROM filtered WHERE city IS NOT NULL AND country <> 'SG'), not_flagged AS (SELECT s.* FROM valid s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.cost BETWEEN 630 AND 690)), eligible AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.brand IN ('Acme', 'Umbrella', 'Globex'))), valid_suppliers AS (SELECT id, supplier_name, rating_whole, resolved_city, country_title, city_filled, ROUND(rating_whole / rating, 2) AS rating_whole_per_rating FROM eligible WHERE supplier_name IS NOT NULL), with_last AS (SELECT s.*, top1.cost FROM valid_suppliers s JOIN LATERAL (SELECT c.cost FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT CASE WHEN rating_whole_per_rating >= 80 THEN 'LARGE' ELSE 'SMALL' END AS rating_whole_per_rating_tier, COUNT(*) AS event_count, ROUND(AVG(rating_whole), 2) AS avg_rating_whole FROM with_last GROUP BY rating_whole_per_rating_tier;
